create temporary view fll_parse_${grass_region_without_quote} as
select
    user_id
    ,transform(data, x -> x.item_id) AS items
    ,timestamp as event_time
    ,biz_info.rcmd_info.bundle as bundle
from
    srdi_rt.ods_fll_rcmd
where
    regional_date = ${regional_date}
    and country = ${grass_region}
    and sample_info.user_sampled = true
;

--sql_divide_splitter--
INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_rcmd_fll_sampled_user_impression_1d
partition(grass_region=${grass_region}, regional_date=${regional_date})
select /*+ REPARTITION(1000) */
    user_id
    ,item_id
    ,case
        when bundle = 'daily_discover_main' then 'DA_Daily Discover'
        when bundle = 'product_detail_page' then 'DA_You May Also Like'
     end as scenario_tag
    ,event_time
from
    fll_parse_${grass_region_without_quote}
    lateral view explode(items) as item_id
where
    bundle in ('daily_discover_main', 'product_detail_page')
;
